1	import { randomInt } from "node:crypto";
2	import { StateView } from "@colyseus/schema";
3	import { ErrorCode, matchMaker, Room, ServerError, type AuthContext, type Client, type Deferred } from "colyseus";
4	import { privateMatch } from "@pirate-sea-race/content";
5	import { encounterRules, type EncounterRules } from "@pirate-sea-race/content/encounters";
6	import {
7	  createMatchOptionsSchema,
8	  DUEL_RECONNECT_SECONDS,
9	  DuelMessageType,
10	  duelReadyMessageSchema,
11	  JoinRefusal,
12	  joinMatchOptionsSchema,
13	  MATCH_CODE_REQUIRED_MESSAGE,
14	  MATCH_ROOM,
15	  MATCH_UNAVAILABLE_MESSAGE,
16	  matchFullMessage,
17	  MAX_CHOOSE_THEFT_PER_SECOND,
18	  MAX_INPUT_MESSAGES_PER_SECOND,
19	  MessageType,
20	  NO_SUCH_MATCH_MESSAGE,
21	  PROTOCOL_VERSION,
22	  RubbingMessageType,
23	  validateChooseTheftMessage,
24	} from "@pirate-sea-race/protocol";
25	import {
26	  addShip,
27	  canSee,
28	  createMatchState,
29	  defaultSimulationConfig,
30	  GRAPPLE_BUTTON,
31	  INTERACT_BUTTON,
