46	  type PlayerInput,
47	} from "@pirate-sea-race/simulation";
48	import type { PlayerIndex } from "@pirate-sea-race/simulation/duel";
49	import {
50	  createEncounterConfig,
51	  createEncounterState,
52	  duelOf,
53	  stepEncounters,
54	  type DuelReport,
