584	  /**
585	   * One world tick of §6 (`stepEncounters`): this tick's snapshot of every ship, the reports of duels that ended since
586	   * the last tick and of duels the ledger has settled, then the events applied. The rules alone choose targets, land
587	   * or miss grapples, start fights and decide returns; the room moves ships and runs the duels.
588	   */
589	  private stepEncounters(frame: number, held: ReadonlySet<string>): void {
590	    const tick = this.simulation.worldTick;
591	    const endedBy = this.protectionEndedNext;
592	    this.protectionEndedNext = new Set();
593	    const players: EncounterPlayerInput[] = this.simulation.ships.map((ship) => {
594	      const gate = this.gates.get(ship.id);
595	      const duel = this.duelOfSession(ship.id);
596	      return {
597	        id: ship.id,
598	        mode: "ship",
599	        x: ship.x,
600	        y: ship.y,
601	        heading: ship.heading,
602	        connected: this.clients.get(ship.id) !== undefined,
603	        attack: !held.has(ship.id) && gate !== undefined && !gate.lapsedAt(frame) && (gate.inputAt(frame).buttons & GRAPPLE_BUTTON) !== 0,
604	        ready: duel?.machine.isReady(ship.id) === true,
605	        // §6: last tick's collection or cache claim ended this player's protection.
606	        protectionEndedBy: endedBy.has(ship.id) ? "collection" : null,
607	      };
608	    });
609	    const stepped = stepEncounters(this.encounterConfig, this.encounters, { tick, players, reports: this.duelReports(tick), matchOver: false });
610	    this.encounters = stepped.state;
611	    for (const event of stepped.events) this.apply(event);
612	    for (const duel of [...this.seaDuels.values()]) if (duel.removeAfterTick !== undefined && tick > duel.removeAfterTick) this.closeSeaDuel(duel);
613	  }
614	
615	  /**
616	   * The reports for this tick. A fight that ended since the last tick is reported to the ledger (unless a player's
617	   * leaving already decided it there) and its end to the rules, as the ledger recorded it. A duel the ledger has
618	   * settled (at once for a draw, a cancellation or a win with nothing to steal; otherwise at the winner's choice or the
619	   * deadline's default) gets its `settled` report, never before: only then do its players return.
620	   */
621	  private duelReports(tick: number): DuelReport[] {
622	    const reports: DuelReport[] = [];
623	    for (const duel of this.seaDuels.values()) {
624	      const outcome = duel.machine.outcome;
625	      if (outcome !== undefined && !duel.ended) {
626	        duel.ended = true;
627	        if (findDuel(this.ledger, duel.id)?.phase === "fighting") {
628	          const winner = outcome.winner === null ? null : duel.players[outcome.winner];
629	          // §12: both fighters forfeiting on the same frame cancels; a double KO or an exact tie is a draw.
630	          const result = winner !== null ? "win" : outcome.reason === "forfeit" || outcome.reason === "cancelled" ? "cancelled" : "draw";
631	          this.ledgerStep("reportDuelResult", reportDuelResult(this.ledger, { duelId: duel.id, tick, outcome: result, ...(winner !== null ? { winner } : {}) }));
632	        }
633	        if (!duel.endedByRules) reports.push(this.endReport(duel, tick));
634	      }
635	      if (!duel.ended || duel.settled) continue;
636	      const settled = findDuel(this.ledger, duel.id);
637	      if (settled === undefined || settled.phase === "settled") {
638	        duel.settled = true;
639	        const endTick = this.encounters.duels.find((each) => each.id === duel.id)?.end?.tick ?? tick;
640	        reports.push({ kind: "settled", duelId: duel.id, tick: Math.min(tick, Math.max(endTick, settled?.settlement?.tick ?? tick)) });
641	      }
642	    }
643	    return reports;
644	  }
