704	  /** A grapple landed: both ships stop, and their duel's countdown starts, in its lobby and marker. */
705	  private openSeaDuel(id: string, players: readonly [string, string], x: number, y: number, tick: number): void {
706	    // A winner who attacks again while the last result is still showing: that lobby goes now.
707	    for (const duel of [...this.seaDuels.values()]) if (duel.players.some((player) => players.includes(player))) this.closeSeaDuel(duel);
708	    for (const player of players) if (this.simulation.ships.some((ship) => ship.id === player)) this.simulation = stopShip(this.simulation, player);
709	    const key = `d${this.nextDuelKey++}`;
710	    const lobby = new SeaDuelSchema();
711	    lobby.code = this.state.code;
712	    lobby.practice = false;
713	    this.state.duels.set(key, lobby);
714	    const machine = new DuelMachine({
715	      lobby,
716	      seed: this.tuning.random(0, 2 ** 32),
717	      start: "called",
718	      send: (sessionId, type, message) => this.clients.get(sessionId)?.send(type, message),
719	    });
720	    players.forEach((player, slot) => {
721	      machine.addSeat(player, slot as PlayerIndex);
722	      if (this.clients.get(player) === undefined) machine.drop(player);
723	    });
724	    // A player grappled while away counts as away from the duel from its start.
725	    for (const player of players) {
726	      const away = this.away.get(player);
727	      if (away !== undefined) away.duelAbsentSince = tick;
728	    }
729	    machine.beginCountdown();
730	    const marker = new DuelMarkerSchema();
731	    marker.x = x;
732	    marker.y = y;
733	    marker.startTick = tick;
734	    this.state.markers.set(key, marker);
735	    this.seaDuels.set(id, { id, key, players, lobby, machine, endedByRules: false, ended: false, settled: false, removeAfterTick: undefined });
736	  }
