738	  /**
739	   * §4 and §12's holds, one world tick: a connected player moored at a dock, out of any duel and holding E works on
740	   * E's target there (`interactTarget`). The same target as their hold continues it; another starts a new hold from
741	   * zero; no E, no mooring or no target cancels it (the ledger's rule: progress resets). Starting one ends protection
742	   * on the next tick.
743	   */
744	  private stepChannels(frame: number, tick: number): void {
745	    const held = this.heldPlayers();
746	    const ships = new Map(this.simulation.ships.map((ship) => [ship.id, ship]));
747	    for (const player of this.ledger.players) {
748	      if (player.status !== "connected") continue;
749	      const id = player.id;
750	      const ship = ships.get(id);
751	      const gate = this.gates.get(id);
752	      const holding =
753	        ship !== undefined && gate !== undefined && ship.dock !== NOT_DOCKED && !held.has(id) && !gate.lapsedAt(frame) && (gate.inputAt(frame).buttons & INTERACT_BUTTON) !== 0;
754	      const target = holding ? interactTarget(this.ledger, this.config.map, id, ship.dock) : undefined;
755	      if (target === undefined) {
756	        if (player.channel !== null) this.ledgerStep("cancelChannel", cancelChannel(this.ledger, { playerId: id, tick }));
757	        continue;
758	      }
759	      if (sameTarget(player.channel, target)) {
760	        const result = this.ledgerStep("progressChannel", progressChannel(this.ledger, { playerId: id, tick }));
761	        if (result.status === "collected" || result.status === "claimed" || result.status === "failed") {
762	          const notice = this.noticesOf(id);
763	          notice.channelResult = result.status === "failed" ? `failed:${result.failure}` : `${result.status}:${target.type}`;
764	          notice.channelResultAt = tick;
765	        }
766	        continue;
767	      }
768	      const started =
769	        target.kind === "collect"
770	          ? this.ledgerStep("startCollect", startCollect(this.ledger, { playerId: id, sourceId: target.sourceId, tick }))
771	          : this.ledgerStep("startCacheClaim", startCacheClaim(this.ledger, { playerId: id, cacheId: target.cacheId, rubbingId: target.rubbingId, tick }));
772	      if (started.ok) this.protectionEndedNext.add(id);
773	    }
774	  }
