776	  /** §4's theft choice from a client: the winner of a duel at sea, in its window, for an eligible type. */
777	  private receiveTheftChoice(sessionId: string, message: unknown): void {
778	    const frame = this.simulation.frame;
779	    const rate = this.choiceRate.get(sessionId) ?? { windowStart: frame, count: 0 };
780	    if (frame - rate.windowStart >= STEPS_PER_SECOND) {
781	      rate.windowStart = frame;
782	      rate.count = 0;
783	    }
784	    rate.count++;
785	    this.choiceRate.set(sessionId, rate);
786	    if (rate.count > MAX_CHOOSE_THEFT_PER_SECOND) return;
787	    const choice = validateChooseTheftMessage(message);
788	    if (choice === undefined) return;
789	    const duel = [...this.seaDuels.values()].find((each) => each.key === choice.duel && each.players.includes(sessionId));
790	    if (duel === undefined) return;
791	    // The ledger checks that this player won, the window is open and the type is eligible; otherwise nothing changes.
792	    const stepped = chooseTheft(this.ledger, { duelId: duel.id, playerId: sessionId, type: choice.type, tick: this.simulation.worldTick });
793	    this.ledger = stepped.state;
794	    this.noteSettlements();
795	  }
