797	  private noticesOf(id: string): Notices {
798	    let notices = this.notices.get(id);
799	    if (notices === undefined) {
800	      notices = { channelResult: "", channelResultAt: 0, settledRole: "", stolen: "", goldChange: 0, settledAt: 0, settledChoice: "", choiceDeadline: 0 };
801	      this.notices.set(id, notices);
802	    }
803	    return notices;
804	  }
