806	  /** Each newly settled ledger duel, in its players' notices: what was stolen and the gold that moved. */
807	  private noteSettlements(): void {
808	    for (const duel of this.ledger.duels) {
809	      if (duel.phase !== "settled" || this.noticed.has(duel.id)) continue;
810	      this.noticed.add(duel.id);
811	      this.noteSettlement(duel);
812	    }
