815	  private noteSettlement(duel: LedgerDuel): void {
816	    const settlement = duel.settlement!;
817	    const result = duel.result!;
818	    for (const id of duel.players) {
819	      const notice = this.noticesOf(id);
820	      notice.settledAt = settlement.tick;
821	      notice.stolen = settlement.stolenType ?? "";
822	      notice.settledChoice = settlement.choice;
823	      notice.choiceDeadline = duel.choiceDeadline ?? 0;
824	      if (result.outcome !== "win") {
825	        notice.settledRole = "draw";
826	        notice.goldChange = 0;
827	      } else {
828	        const winner = result.winner === id;
829	        notice.settledRole = winner ? "winner" : "loser";
830	        notice.goldChange = winner ? settlement.gold : -settlement.gold;
831	      }
832	    }
833	  }
