835	  /**
836	   * After every world tick in development and tests: the ledger's own invariant, and the room's: every player the
837	   * ledger counts in the match has a ship, and every ship belongs to such a player.
838	   */
839	  private checkInvariants(tick: number): void {
840	    if (!this.tuning.checkInvariants) return;
841	    const problems = checkLedger(this.ledger);
842	    const ships = new Set(this.simulation.ships.map((ship) => ship.id));
843	    for (const player of this.ledger.players) {
844	      if (player.status !== "left" && !ships.has(player.id)) problems.push(`player ${player.id} is in the ledger's match without a ship`);
845	    }
846	    for (const id of ships) {
847	      const player = findPlayer(this.ledger, id);
848	      if (player === undefined || player.status === "left") problems.push(`ship ${id} has no player in the ledger's match`);
849	    }
850	    if (problems.length === 0) return;
851	    for (const problem of problems) this.violations.push(`tick ${tick}: ${problem}`);
852	    console.error(`match ${this.state.code} invariant violated at tick ${tick}: ${problems.join("; ")}`);
853	  }
