855	  /** Copies the plain simulation state into the synced schema, then updates what each client may see. */
856	  private mirror(): void {
857	    this.state.frame = this.simulation.frame;
858	    this.state.worldTick = this.simulation.worldTick;
859	    this.state.players = this.simulation.ships.length;
860	    const present = new Set<string>();
861	    for (const ship of this.simulation.ships) {
862	      present.add(ship.id);
863	      let synced = this.state.ships.get(ship.id);
864	      if (synced === undefined) {
865	        synced = new ShipSchema();
866	        synced.id = ship.id;
867	        synced.slot = ship.slot;
868	        this.state.ships.set(ship.id, synced);
869	      }
870	      synced.x = ship.x;
871	      synced.y = ship.y;
872	      synced.heading = ship.heading;
873	      synced.speed = ship.speed;
874	      synced.dock = ship.dock;
875	    }
876	    for (const id of [...this.state.ships.keys()]) if (!present.has(id)) this.state.ships.delete(id);
877	    this.mirrorEncounters(present);
878	    this.mirrorObjectives(present);
879	    this.updateViews();
880	  }
