882	  /** The rules' telegraphs and each player's status into the synced state (markers change only on events). */
883	  private mirrorEncounters(present: ReadonlySet<string>): void {
884	    const keys = new Set<string>();
885	    for (const attempt of this.encounters.attempts) {
886	      for (const [key, defenderId] of [
887	        [attempt.attackerId, attempt.defenderId],
888	        [attempt.attackerId + BLANK_GRAPPLE_SUFFIX, ""],
889	      ] as const) {
890	        keys.add(key);
891	        let synced = this.state.grapples.get(key);
892	        if (synced === undefined) {
893	          synced = new GrappleSchema();
894	          synced.attackerId = attempt.attackerId;
895	          this.state.grapples.set(key, synced);
896	        }
897	        synced.defenderId = defenderId;
898	        synced.aim = attempt.aim;
899	        synced.startTick = attempt.startTick;
900	        synced.landTick = attempt.landTick;
901	      }
902	    }
903	    for (const key of [...this.state.grapples.keys()]) if (!keys.has(key)) this.state.grapples.delete(key);
904	
905	    const records = new Map(this.encounters.players.map((player) => [player.id, player]));
906	    for (const id of present) {
907	      let status = this.state.status.get(id);
908	      if (status === undefined) {
909	        status = new PlayerStatusSchema();
910	        this.state.status.set(id, status);
911	      }
912	      const record = records.get(id);
913	      status.mode = record?.respawn != null ? "respawning" : duelOf(this.encounters, id) !== undefined ? "duel" : "sea";
914	      status.protection = record?.protection?.source ?? "";
915	      status.protectedUntil = record?.protection?.endTick ?? 0;
916	      status.cooldownUntil = record?.cooldownEndTick ?? 0;
917	      status.respawnAt = record?.respawn?.respawnTick ?? 0;
918	    }
919	    for (const id of [...this.state.status.keys()]) if (!present.has(id)) this.state.status.delete(id);
920	  }
