922	  /**
923	   * The ledger into the synced state: each player's private status (gold, rubbings, what their island and dock hold
924	   * while moored there, E's target and progress, their theft choice and their last results), and a contentless marker
925	   * for each recovery cache.
926	   */
927	  private mirrorObjectives(present: ReadonlySet<string>): void {
928	    const map = this.config.map;
929	    const ships = new Map(this.simulation.ships.map((ship) => [ship.id, ship]));
930	    const held = this.heldPlayers();
931	    for (const id of present) {
932	      const status = this.state.status.get(id)!;
933	      const player = findPlayer(this.ledger, id);
934	      const ship = ships.get(id)!;
935	      const moored = ship.dock !== NOT_DOCKED && !held.has(id) && player !== undefined;
936	      status.gold = player?.gold ?? 0;
937	      status.rubbings = player === undefined ? "" : heldTypes(this.ledger, id).join(",");
938	      status.islandTypes = moored ? sealedTypesAt(this.ledger, map.docks[ship.dock]!.island).join(",") : "";
939	      status.cacheTypes = moored ? cachedTypesAt(this.ledger, map, ship.dock).join(",") : "";
940	      const target = moored && player.status === "connected" ? interactTarget(this.ledger, map, id, ship.dock) : undefined;
941	      status.target = target === undefined ? "" : `${target.kind}:${target.type}`;
942	      const channel = player?.channel ?? null;
943	      status.channel = channel?.kind ?? "";
944	      status.channelType = channel === null ? "" : (this.ledger.rubbings.find((rubbing) => rubbing.id === channel.rubbingId)?.type ?? "");
945	      status.channelHeld = channel?.heldTicks ?? 0;
946	      status.channelTotal = channel === null ? 0 : channel.kind === "collect" ? this.ledger.rules.collectTicks : this.ledger.rules.cacheClaimTicks;
947	      const choosing = this.ledger.duels.find((duel) => duel.phase === "choosing" && duel.result?.winner === id);
948	      const options = choosing === undefined ? [] : eligibleTheftTypes(this.ledger, choosing.id);
949	      status.theftDuel = choosing === undefined || options.length === 0 ? "" : (this.seaDuels.get(choosing.id)?.key ?? "");
950	      status.theftOptions = status.theftDuel === "" ? "" : options.join(",");
951	      status.theftDeadline = status.theftDuel === "" ? 0 : choosing!.choiceDeadline!;
952	      const notice = this.noticesOf(id);
953	      status.channelResult = notice.channelResult;
954	      status.channelResultAt = notice.channelResultAt;
955	      status.settledRole = notice.settledRole;
956	      status.stolen = notice.stolen;
957	      status.goldChange = notice.goldChange;
958	      status.settledAt = notice.settledAt;
959	      status.settledChoice = notice.settledChoice;
960	      status.choiceDeadline = notice.choiceDeadline;
961	    }
962	    const caches = new Set<string>();
963	    for (const cache of this.ledger.caches) {
964	      if (cacheRubbings(this.ledger, cache.id).length === 0) continue;
965	      caches.add(cache.id);
966	      let synced = this.state.caches.get(cache.id);
967	      if (synced === undefined) {
968	        synced = new CacheMarkerSchema();
969	        synced.x = cache.x;
970	        synced.y = cache.y;
971	        synced.dock = cacheDock(map, cache);
972	        this.state.caches.set(cache.id, synced);
973	      }
974	    }
975	    for (const id of [...this.state.caches.keys()]) if (!caches.has(id)) this.state.caches.delete(id);
976	  }
977	
978	  /**
979	   * Each client's view (§3, §6, §12, §16): its own ship unless it waits to respawn, the ships it can see that are not
980	   * in a duel or waiting to respawn, the grapples whose attacker it sees or that aim at it (with the target blanked
981	   * unless it sees the target too), the duel markers and caches in its sight, its own status and its own duel. A
982	   * fighter or a player waiting to respawn sees no other ship, grapple, marker or cache. Nothing else is encoded for it.
983	   */
984	  private updateViews(): void {
985	    const inDuel = new Set(this.encounters.duels.flatMap((duel) => duel.players));
986	    const respawning = new Set(this.encounters.players.filter((player) => player.respawn !== null).map((player) => player.id));
987	    const ships = new Map(this.simulation.ships.map((ship) => [ship.id, ship]));
988	    for (const client of this.clients) {
989	      const view = client.view;
990	      if (view === undefined) continue;
991	      const self = client.sessionId;
992	      const viewer = ships.get(self);
993	      const away = inDuel.has(self) || respawning.has(self);
994	      const sync = (item: Parameters<typeof view.add>[0], visible: boolean) => {
995	        const shown = view.has(item);
996	        if (visible && !shown) view.add(item);
997	        else if (!visible && shown) view.remove(item);
998	      };
999	      const visible = visibleShipIds(this.config, this.simulation, self);
1000	      for (const [id, ship] of this.state.ships) {
1001	        sync(ship, id === self ? !respawning.has(id) : visible.has(id) && !away && !inDuel.has(id) && !respawning.has(id));
1002	      }
1003	      const sees = (id: string) => {
1004	        const other = ships.get(id);
1005	        return !away && viewer !== undefined && other !== undefined && canSee(this.config, viewer, other);
1006	      };
1007	      for (const attempt of this.encounters.attempts) {
1008	        const aimedAt = attempt.attackerId === self || attempt.defenderId === self;
1009	        const full = aimedAt || (sees(attempt.attackerId) && sees(attempt.defenderId));
1010	        const blank = !full && sees(attempt.attackerId);
1011	        const fullEntry = this.state.grapples.get(attempt.attackerId);
1012	        const blankEntry = this.state.grapples.get(attempt.attackerId + BLANK_GRAPPLE_SUFFIX);
1013	        if (fullEntry !== undefined) sync(fullEntry, full);
1014	        if (blankEntry !== undefined) sync(blankEntry, blank);
1015	      }
1016	      for (const marker of this.state.markers.values()) sync(marker, !away && viewer !== undefined && pointInSight(this.config, viewer, marker));
1017	      for (const cache of this.state.caches.values()) sync(cache, !away && viewer !== undefined && pointInSight(this.config, viewer, cache));
1018	      for (const [id, status] of this.state.status) sync(status, id === self);
1019	      for (const lobby of this.state.duels.values()) sync(lobby, lobby.seats.some((seat) => seat.sessionId === self));
1020	    }
1021	  }
1022	
1023	  private async allocateCode(): Promise<string> {
1024	    for (let attempt = 0; attempt < 16; attempt++) {
1025	      const code = generateMatchCode();
1026	      const taken = await matchMaker.query({ name: this.roomName, code });
1027	      if (taken.length === 0) return code;
1028	    }
1029	    throw new ServerError(JoinRefusal.BadRequest, "Could not allocate a match code");
1030	  }
1031	}
