import { schema, t, type SchemaType } from "@colyseus/schema";

/**
 * The synced mirror of the plain simulation state. The room copies the simulation into it after every world step;
 * Colyseus sends clients the deltas at the patch rate. Clients decode it by reflection and import these types only.
 */
export const ShipSchema = schema(
  {
    id: t.string(),
    slot: t.uint8(),
    x: t.int32(),
    y: t.int32(),
    heading: t.uint8(),
    speed: t.int16(),
    /** The dock the ship is moored at, or -1 at sea. */
    dock: t.int8(),
  },
  "Ship",
);
export type ShipSchema = SchemaType<typeof ShipSchema>;

/**
 * A telegraphed grapple (§6), from the press until it lands: the attacker, the target the rules chose, the aim locked
 * at the start (a heading of 64) and the world ticks it started and lands on. Keyed by the attacker's id. Each attempt
 * has a second entry, keyed `<attacker id>~`, with `defenderId` blank (§16): a viewer who sees the attacker but not the
 * defender gets that one, so the target's id never reaches them. A view holds at most one of the two.
 */
export const GrappleSchema = schema(
  {
    attackerId: t.string(),
    defenderId: t.string(),
    aim: t.uint8(),
    startTick: t.uint32(),
    landTick: t.uint32(),
  },
  "Grapple",
);
export type GrappleSchema = SchemaType<typeof GrappleSchema>;

/**
 * A duel marker (§6): where a duel runs and the world tick it was reserved on, so players in sight can show crossed
 * swords and the elapsed time. Keyed by an opaque id: nothing names the fighters.
 */
export const DuelMarkerSchema = schema(
  {
    x: t.int32(),
    y: t.int32(),
    startTick: t.uint32(),
  },
  "DuelMarker",
);
export type DuelMarkerSchema = SchemaType<typeof DuelMarkerSchema>;

/**
 * A recovery cache (§12) as others see it: a marker at a dock, with no contents. A player moored at that dock reads
 * the contents in their own status (`cacheTypes`). Keyed by the cache's id.
 */
export const CacheMarkerSchema = schema(
  {
    x: t.int32(),
    y: t.int32(),
    dock: t.int8(),
  },
  "CacheMarker",
);
export type CacheMarkerSchema = SchemaType<typeof CacheMarkerSchema>;

/**
 * A player's own encounter status, for their HUD only: protection and its source until a world tick, the grapple's
 * miss cooldown, and the respawn tick while they wait out of the world after losing a duel (0 when none).
 */
export const PlayerStatusSchema = schema(
  {
    /** "sea", "duel" (reserved or fighting, until the duel is settled) or "respawning". */
    mode: t.string(),
    /** "spawn", "win", "draw", "respawn", or empty when unprotected. */
    protection: t.string(),
    protectedUntil: t.uint32(),
    cooldownUntil: t.uint32(),
    respawnAt: t.uint32(),
    /** §11: the player's gold (the ledger's balance). Private, like everything in this entry (§16). */
    gold: t.uint16(),
    /** §4: the rubbing types the player holds, in type order, comma-separated ("sun,moon"), reserved ones included. */
    rubbings: t.string(),
    /** The types still sealed at the island the player is moored at, one per source (empty when not moored). */
    islandTypes: t.string(),
    /** The types in recovery caches at the dock the player is moored at, one per rubbing (empty when not moored). */
    cacheTypes: t.string(),
    /** What holding E works on here: "collect:<type>", "claim:<type>", or empty. */
    target: t.string(),
    /** The hold in progress: "collect" or "claim", or empty. */
    channel: t.string(),
    channelType: t.string(),
    /** Ticks held so far, and the ticks the hold needs (§4: six seconds). */
    channelHeld: t.uint16(),
    channelTotal: t.uint16(),
    /** The last finished hold: "collected:<type>", "claimed:<type>" or "failed:<reason>", and its world tick. */
    channelResult: t.string(),
    channelResultAt: t.uint32(),
    /** §4: while this player, having won, chooses: their duel lobby's key, the eligible types, and the deadline tick. */
    theftDuel: t.string(),
    theftOptions: t.string(),
    theftDeadline: t.uint32(),
    /** The last duel settlement: "winner", "loser" or "draw" (empty before any), the type stolen, the gold change. */
    settledRole: t.string(),
    stolen: t.string(),
    goldChange: t.int16(),
    settledAt: t.uint32(),
    /**
     * Who picked the stolen type: "winner", "default" (the deadline applied it), "none" (nothing moved), or empty
     * before any settlement; and that duel's choice deadline tick (0 when it had no choice window).
     */
    settledChoice: t.string(),
    choiceDeadline: t.uint32(),
  },
  "PlayerStatus",
);
export type PlayerStatusSchema = SchemaType<typeof PlayerStatusSchema>;

/** One seat of a duel: its player index (slot 0 is player one, the creator), its session and whether it is connected. */
export const DuelSeatSchema = schema(
  {
    sessionId: t.string(),
    slot: t.uint8(),
    connected: t.boolean(),
    /** The latest round trip the server measured for this seat, in milliseconds. */
    rtt: t.uint16(),
  },
  "DuelSeat",
);
export type DuelSeatSchema = SchemaType<typeof DuelSeatSchema>;

/**
 * A duel room's lobby state, synced at the patch rate. The duel's frame data does not travel here: inputs, applied
 * inputs, hashes and snapshots are Colyseus messages (the duel protocol in docs/duel.md).
 */
export const DuelRoomStateSchema = schema(
  {
    code: t.string(),
    protocolVersion: t.uint16(),
    /** A practice room: one player against the server's dummy (player two). */
    practice: t.boolean(),
    /** The dummy's behaviour in a practice room ("idle" or "guard"), empty otherwise. */
    dummy: t.string(),
    /** "waiting", "countdown", "fighting" or "over". */
    phase: t.string(),
    /** Frames left in the countdown. */
    countdown: t.uint16(),
    /** The seed both sides create the duel's frame-0 state from. */
    seed: t.uint32(),
    /** The shared input delay in frames, once chosen (0 before). */
    inputDelay: t.uint8(),
    seats: t.array(DuelSeatSchema),
    /** Once over: the winner's slot, or -1 for a draw. */
    winner: t.int8(),
    /** Once over: "ko", "double-ko", "timeout", "overtime" or "forfeit". */
    reason: t.string(),
    /** Once over: the frame the duel ended on. */
    resultFrame: t.uint32(),
  },
  "DuelRoomState",
);
export type DuelRoomStateSchema = SchemaType<typeof DuelRoomStateSchema>;

/**
 * A duel at sea (§14: a simulation object inside the match room): the same lobby a standalone duel room syncs, for its
 * two fighters only. Slot 0 is the attacker, slot 1 the grappled ship. The duel's frames travel as messages, as in a
 * duel room.
 */
export const SeaDuelSchema = schema(
  {
    /** The match code, for the duel HUD. */
    code: t.string(),
    /** Always false: practice is a standalone duel room. */
    practice: t.boolean(),
    /** "countdown", "waiting" (a fighter still loading after the countdown), "fighting" or "over". */
    phase: t.string(),
    countdown: t.uint16(),
    seed: t.uint32(),
    inputDelay: t.uint8(),
    seats: t.array(DuelSeatSchema),
    winner: t.int8(),
    /** Once over: "ko", "double-ko", "timeout", "overtime", "forfeit" or "cancelled". */
    reason: t.string(),
    resultFrame: t.uint32(),
  },
  "SeaDuel",
);
export type SeaDuelSchema = SchemaType<typeof SeaDuelSchema>;

export const MatchStateSchema = schema(
  {
    code: t.string(),
    protocolVersion: t.uint16(),
    /** Private matches are custom matches (§2). */
    custom: t.boolean(),
    /** Players in the match, visible or not. */
    players: t.uint8(),
    /** The simulation frame at the last world step. */
    frame: t.uint32(),
    worldTick: t.uint32(),
    /**
     * Filtered per client (§16): each client's StateView holds its own ship and the ships inside its sight radius,
     * less those in a duel or waiting to respawn (§6), and Colyseus encodes no other entry of this map into that
     * client's messages.
     */
    ships: t.map(ShipSchema).view(),
    /** Telegraphed grapples, filtered like ships: each client's view holds those whose attacker it sees, or aimed at it. */
    grapples: t.map(GrappleSchema).view(),
    /** Duel markers, filtered like ships: each client's view holds those within its sight radius. */
    markers: t.map(DuelMarkerSchema).view(),
    /** Recovery caches, filtered like ships: each client's view holds those within its sight radius (§12, §16). */
    caches: t.map(CacheMarkerSchema).view(),
    /** Each client's view holds only its own entry: its encounter status, gold, rubbings and holds (§16). */
    status: t.map(PlayerStatusSchema).view(),
    /** Duels at sea: each client's view holds only the one it fights in. */
    duels: t.map(SeaDuelSchema).view(),
  },
  "MatchState",
);
export type MatchStateSchema = SchemaType<typeof MatchStateSchema>;

import type { AddressInfo } from "node:net";
import { createEndpoint, createRouter, defineRoom, defineServer, matchMaker, WebSocketTransport, type Server } from "colyseus";
import { createTestPlacementSchema, DUEL_ROOM, MATCH_ROOM, TEST_PLACEMENT_PATH } from "@pirate-sea-race/protocol";
import { defaultSimulationConfig } from "@pirate-sea-race/simulation";
import { DuelRoom } from "./DuelRoom.js";
import { DEFAULT_MATCH_TUNING, MatchRoom, type MatchTuning } from "./MatchRoom.js";

export const DEFAULT_PORT = 2593;

/** The largest WebSocket frame the transport accepts; a larger one closes that connection. */
export const MAX_FRAME_BYTES = 4096;

export interface GameServerOptions {
  /** 0 picks a free port. */
  readonly port: number;
  readonly host?: string;
  /** Install SIGINT/SIGTERM handlers that drain rooms and exit. Off for in-process tests. */
  readonly handleSignals?: boolean;
  /**
   * Test-only: serve TEST_PLACEMENT_PATH, which puts a player's ship on a chosen tile. Off by default; only the dev
   * and test entry point (`dev.ts`) and in-process tests turn it on.
   */
  readonly testPlacement?: boolean;
  /**
   * Test-only: a match's timings and settings instead of the rules' (`DEFAULT_MATCH_TUNING`), for example a short seat
   * reservation or respawn delay, or a pinned source layout. Unset in production (`main.ts` never passes it).
   */
  readonly matchTuning?: Partial<MatchTuning>;
  /** Test-only: a standalone duel's reconnection window in seconds instead of DUEL_RECONNECT_SECONDS. */
  readonly duelReconnectSeconds?: number;
  /**
   * Check the ledger and the room's invariants after every world tick (on by default, for development and tests); the
   * production entry turns it off.
   */
  readonly checkInvariants?: boolean;
}

export interface RunningGameServer {
  readonly port: number;
  readonly server: Server;
  close(): Promise<void>;
}

/** Placements on the match's own sea map. */
const testPlacementSchema = createTestPlacementSchema(defaultSimulationConfig.map);

/**
 * POST TEST_PLACEMENT_PATH with a TestPlacement body: 200 with the ship's new position, 400 for a malformed body, a
 * tile off the map or a tile a ship cannot sit on, 404 when no match or player matches.
 */
const placeShipEndpoint = createEndpoint(TEST_PLACEMENT_PATH, { method: "POST" }, async (context) => {
  const parsed = testPlacementSchema.safeParse(context.body);
  if (!parsed.success) return Response.json({ error: "malformed placement" }, { status: 400 });
  const { code, sessionId, tileX, tileY, heading } = parsed.data;
  const [listing] = await matchMaker.query({ name: MATCH_ROOM, code });
  const room = listing === undefined ? undefined : (matchMaker.getLocalRoomById(listing.roomId) as MatchRoom | undefined);
  if (room === undefined || room.clients.get(sessionId) === undefined) return Response.json({ error: "no such player" }, { status: 404 });
  try {
    room.placeShip(sessionId, { tileX, tileY, heading });
  } catch (error) {
    return Response.json({ error: (error as Error).message }, { status: 400 });
  }
  const ship = room.state.ships.get(sessionId)!;
  return Response.json({ x: ship.x, y: ship.y, heading: ship.heading });
});

/** The room classes a server registers: the rules' own, or subclasses carrying the test-only settings. */
function roomClasses(options: GameServerOptions): { match: typeof MatchRoom; duel: typeof DuelRoom } {
  const tuning: MatchTuning = { ...DEFAULT_MATCH_TUNING, ...options.matchTuning, checkInvariants: options.checkInvariants ?? options.matchTuning?.checkInvariants ?? true };
  const match = class TunedMatchRoom extends MatchRoom {
    protected override matchTuning(): MatchTuning {
      return tuning;
    }
  };
  const seconds = options.duelReconnectSeconds;
  const duel =
    seconds === undefined
      ? DuelRoom
      : class TunedDuelRoom extends DuelRoom {
          protected override reconnectSeconds(): number {
            return seconds;
          }
        };
  return { match, duel };
}

export async function startGameServer(options: GameServerOptions): Promise<RunningGameServer> {
  const rooms = roomClasses(options);
  const server = defineServer({
    greet: false,
    gracefullyShutdown: options.handleSignals ?? true,
    transport: new WebSocketTransport({ maxPayload: MAX_FRAME_BYTES }),
    rooms: {
      // Private matches are found by their code. A create's one-time token is a filter field too, and no listing
      // holds it, so a request carrying one matches no existing match: `join` fails and `joinOrCreate` creates.
      [MATCH_ROOM]: defineRoom(rooms.match).filterBy(["code", "createToken"]),
      // Standalone duels (the combat spike) are admitted the same way, under their own name.
      [DUEL_ROOM]: defineRoom(rooms.duel).filterBy(["code", "createToken"]),
    },
    ...(options.testPlacement === true ? { routes: createRouter({ placeShipEndpoint }) } : {}),
  });
  await server.listen(options.port, options.host);
  const address = server.transport.server?.address() as AddressInfo | null | undefined;
  return {
    port: address?.port ?? options.port,
    server,
    close: () => server.gracefullyShutdown(false),
  };
}
import { parseTestSourceLayout, TEST_PLACEMENT_ENV, TEST_SOURCES_ENV } from "@pirate-sea-race/protocol";
import { DEFAULT_PORT, startGameServer } from "./server.js";

/**
 * The development and test entry point (`npm run dev`, and `start:source` for the browser tests). Unlike the
 * production entry (`main.ts`), it reads the test-only settings, each off unless its variable is set:
 * PIRATE_SEA_RACE_TEST_PLACEMENT=1 turns on the route that puts ships on chosen tiles, and
 * PIRATE_SEA_RACE_TEST_SOURCES pins every match's source layout (for example `sun,sun|moon,moon|sun,sun|moon,moon`),
 * so a scenario can pick an island by its rubbing type.
 */
const port = Number(process.env["PORT"] ?? DEFAULT_PORT);
const testPlacement = process.env[TEST_PLACEMENT_ENV] === "1";
const layoutSetting = process.env[TEST_SOURCES_ENV];
const sourceLayout = layoutSetting === undefined || layoutSetting === "" ? undefined : parseTestSourceLayout(layoutSetting);
if (layoutSetting !== undefined && layoutSetting !== "" && sourceLayout === undefined) throw new Error(`${TEST_SOURCES_ENV} is malformed: ${layoutSetting}`);
const running = await startGameServer({ port, testPlacement, ...(sourceLayout !== undefined ? { matchTuning: { sourceLayout } } : {}) });
const settings = [testPlacement ? "test placement on" : "", sourceLayout !== undefined ? `test sources ${layoutSetting}` : ""].filter((each) => each !== "");
console.log(`Pirate Sea Race server listening on ws://localhost:${running.port}${settings.length > 0 ? ` (${settings.join(", ")})` : ""}`);
import { DEFAULT_PORT, startGameServer } from "./server.js";

const port = Number(process.env["PORT"] ?? DEFAULT_PORT);
// Production reads no test-only setting, and skips the per-tick invariant checks that development and tests run.
const running = await startGameServer({ port, checkInvariants: false });
console.log(`Pirate Sea Race server listening on ws://localhost:${running.port}`);
export {
  authorizeEntry,
  BLANK_GRAPPLE_SUFFIX,
  cryptoRandom,
  DEFAULT_MATCH_TUNING,
  DUEL_RESULT_TICKS,
  MatchRoom,
  RECONNECTION_OUTER_BOUND_SECONDS,
  type MatchMetadata,
  type MatchTuning,
  type RandomSource,
  type SeaDuelDiagnostics,
} from "./MatchRoom.js";
export {
  cachedTypesAt,
  cacheDock,
  createMatchLedger,
  dockCentre,
  interactTarget,
  layoutAssignment,
  MATCH_PRESET,
  nearestDockBySea,
  sealedTypesAt,
  sourceSites,
  type InteractTarget,
} from "./objectives.js";
export { InputGate, type DropReason } from "./inputGate.js";
export { authorizeDuelEntry, DuelRoom } from "./DuelRoom.js";
export { DELAY_DECISION_FRAMES, DuelMachine, type DuelDiagnostics, type DuelLobbySchema, type DuelOutcome } from "./duelMachine.js";
export { DuelInputGate } from "./duelInputGate.js";
export { generateMatchCode } from "./matchCode.js";
export {
  CacheMarkerSchema,
  DuelMarkerSchema,
  DuelRoomStateSchema,
  DuelSeatSchema,
  GrappleSchema,
  MatchStateSchema,
  PlayerStatusSchema,
  SeaDuelSchema,
  ShipSchema,
} from "./schema.js";
export { DEFAULT_PORT, MAX_FRAME_BYTES, startGameServer, type GameServerOptions, type RunningGameServer } from "./server.js";
import { matchMaker, ServerError } from "colyseus";
import { JoinRefusal, MALFORMED_MATCH_REQUEST_MESSAGE, PROTOCOL_VERSION, protocolMismatchMessage } from "@pirate-sea-race/protocol";

/** Anything with zod's `safeParse`. */
interface Schema {
  safeParse(value: unknown): { success: boolean };
}

/**
 * The private admission rules one kind of room applies (matches and duels share them): its matchmaking name, its
 * create and join option schemas, and its refusal messages.
 */
export interface AdmissionRules {
  readonly roomName: string;
  readonly createSchema: Schema;
  readonly joinSchema: Schema;
  readonly noSuchMessage: string;
  readonly codeRequiredMessage: string;
  readonly fullMessage: (maxClients: number) => string;
}

/**
 * Checks a create or join request before matchmaking places it: Colyseus calls this for every `create`, `join`,
 * `joinOrCreate` and `joinById` before it reserves a seat. A request carries either a `createToken` (a create) or a
 * `code` (a join), never both and never neither. Refusals carry a readable message the client shows.
 */
export async function authorizePrivateEntry(options: unknown, rules: AdmissionRules): Promise<true> {
  const request = (options ?? {}) as { protocolVersion?: unknown; code?: unknown; createToken?: unknown };
  if (request.protocolVersion !== PROTOCOL_VERSION) {
    throw new ServerError(JoinRefusal.ProtocolMismatch, protocolMismatchMessage(request.protocolVersion));
  }
  const hasCode = request.code !== undefined;
  const hasToken = request.createToken !== undefined;
  if (hasCode === hasToken) throw new ServerError(JoinRefusal.BadRequest, MALFORMED_MATCH_REQUEST_MESSAGE);
  if (hasToken) {
    if (!rules.createSchema.safeParse(options).success) throw new ServerError(JoinRefusal.BadRequest, MALFORMED_MATCH_REQUEST_MESSAGE);
    return true;
  }
  if (!rules.joinSchema.safeParse(options).success) throw new ServerError(JoinRefusal.NoSuchMatch, rules.noSuchMessage);
  const [listing] = await matchMaker.query({ name: rules.roomName, code: request.code as string });
  if (listing === undefined) throw new ServerError(JoinRefusal.NoSuchMatch, rules.noSuchMessage);
  if (listing.locked || listing.clients >= listing.maxClients) {
    throw new ServerError(JoinRefusal.MatchFull, rules.fullMessage(listing.maxClients));
  }
  return true;
}

/**
 * The room's own admission check, which also covers `joinById` (no listing filter applies there): the one seat
 * carrying the creator's token, then only seats carrying this room's code. Returns the creator's token still unspent
 * (undefined once the creator's seat is taken); throwing refuses and frees the seat.
 */
export function admitSeat(options: unknown, room: { readonly code: string; readonly createToken: string | undefined }, rules: AdmissionRules): string | undefined {
  const request = (options ?? {}) as { code?: unknown; createToken?: unknown };
  if (request.createToken === undefined) {
    if (request.code === room.code) return room.createToken;
    if (request.code !== undefined) throw new ServerError(JoinRefusal.NoSuchMatch, rules.noSuchMessage);
  } else if (request.code === undefined && room.createToken !== undefined && request.createToken === room.createToken) {
    return undefined;
  }
  throw new ServerError(JoinRefusal.CodeRequired, rules.codeRequiredMessage);
}

