export function grappleLine(model: Pick<HudModel, "selfId" | "encounter" | "grapples" | "worldTick">): HudLine {
  const own = model.grapples.find((grapple) => grapple.attackerId === model.selfId);
  if (own !== undefined) return { text: `Grappling, aimed ${compassOfHeading(own.aim)}`, state: "aiming", seconds: secondsUntil(own.landTick, model.worldTick) };
  const status = model.encounter;
  if (status !== undefined && status.mode !== "sea") return { text: "", state: "unavailable" };
  const cooldown = status === undefined ? 0 : secondsUntil(status.cooldownUntil, model.worldTick);
  if (cooldown > 0) return { text: `J: grapple in ${cooldown} s`, state: "cooldown", seconds: cooldown };
  return { text: "J: grapple a ship ahead", state: "ready" };
}

/** A grapple aimed at this player (§6: escape before it lands), with the side it comes from. */
export function incomingLine(model: Pick<HudModel, "selfId" | "grapples" | "ships" | "worldTick">): HudLine {
  const incoming = model.grapples.find((grapple) => grapple.defenderId === model.selfId);
  if (incoming === undefined) return { text: "", state: "none" };
  const own = model.ships.find((ship) => ship.id === model.selfId);
  const attacker = model.ships.find((ship) => ship.id === incoming.attackerId);
  // Without both ships, the aim still says where it comes from: from the opposite side of its direction.
  const from = own !== undefined && attacker !== undefined ? compassToward(own, attacker) : compassOfHeading(incoming.aim + HEADING_COUNT / 2);
  return { text: `Incoming grapple from the ${from}! Sail out of range or out of its aim`, state: from, seconds: secondsUntil(incoming.landTick, model.worldTick) };
}

const PROTECTION_SOURCES: Record<string, string> = { spawn: "departure", win: "won a duel", draw: "drawn duel", respawn: "respawned" };

/** Escape protection (§6): nobody can grapple this player until it runs out (or it grapples someone). */
export function protectionLine(model: Pick<HudModel, "encounter" | "worldTick">): HudLine {
  const status = model.encounter;
  if (status === undefined || status.protection === "") return { text: "", state: "none" };
  const seconds = secondsUntil(status.protectedUntil, model.worldTick);
  return { text: `Protected for ${seconds} s (${PROTECTION_SOURCES[status.protection] ?? status.protection})`, state: status.protection, seconds };
}

/** The loser's wait out of the world (§6): 15 s from the end of the fight, then a dock. */
export function respawnLine(model: Pick<HudModel, "encounter" | "worldTick">): HudLine {
  const status = model.encounter;
  if (status === undefined || status.mode !== "respawning") return { text: "", state: "none" };
  const seconds = secondsUntil(status.respawnAt, model.worldTick);
  return { text: `Duel lost: respawning at a dock in ${seconds} s`, state: "respawning", seconds };
}

const TYPE_NAMES: Readonly<Record<string, string>> = { sun: "Sun", moon: "Moon", tide: "Tide", storm: "Storm" };

/** A rubbing type's name as the HUD writes it: "Sun". */
export function typeName(type: string): string {
  return TYPE_NAMES[type] ?? type;
}

/** The rubbings a player holds, by name: "Sun, Moon", or "none yet". */
export function rubbingsText(types: readonly string[]): string {
  return types.length === 0 ? "none yet" : types.map(typeName).join(", ");
}

/**
 * What the island the player is moored at still seals (§4), which the server sends only to players moored there:
 * "Palm Key holds: Sun, Sun", or that it holds nothing more. Empty at sea.
 */
export function islandLine(model: Pick<HudModel, "selfId" | "ships" | "objectives">): HudLine {
  const own = model.ships.find((ship) => ship.id === model.selfId);
  const objectives = model.objectives;
  if (own === undefined || own.dock === NOT_DOCKED || objectives === undefined) return { text: "", state: "none" };
  const island = defaultSimulationConfig.map.islands[defaultSimulationConfig.map.docks[own.dock]?.island ?? -1]?.name ?? "This island";
  if (objectives.islandTypes.length === 0) return { text: `${island} holds no more rubbings`, state: "empty" };
  return { text: `${island} holds: ${objectives.islandTypes.map(typeName).join(", ")}`, state: objectives.islandTypes.join(",") };
}

/** A recovery cache at the dock the player is moored at (§12): its contents, which only a player moored there sees. */
export function cacheLine(model: Pick<HudModel, "objectives">): HudLine {
  const types = model.objectives?.cacheTypes ?? [];
  if (types.length === 0) return { text: "", state: "none" };
  return { text: `Recovery cache here: ${types.map(typeName).join(", ")}`, state: types.join(",") };
}

/**
 * Holding E at a dock (§4, §12): the hold in progress with the seconds left, or what E would do here (the island's
 * rubbing first, then a cache's), or nothing.
 */
export function holdLine(model: Pick<HudModel, "objectives">): HudLine {
  const objectives = model.objectives;
  if (objectives === undefined) return { text: "", state: "none" };
  if (objectives.channel !== "") {
    const seconds = Math.max(0, Math.ceil((objectives.channelTotal - objectives.channelHeld) / WORLD_STEPS_PER_SECOND));
    const what = objectives.channel === "collect" ? `Collecting the ${typeName(objectives.channelType)} rubbing` : `Claiming the ${typeName(objectives.channelType)} rubbing from the cache`;
    return { text: `${what}: keep holding E, ${seconds} s left`, state: `${objectives.channel}:${objectives.channelType}`, seconds };
  }
  const [kind, type] = objectives.target.split(":");
  if (kind === "collect") return { text: `Hold E to collect the ${typeName(type!)} rubbing`, state: `ready:${objectives.target}` };
  if (kind === "claim") return { text: `Hold E to claim the ${typeName(type!)} rubbing from the cache`, state: `ready:${objectives.target}` };
  return { text: "", state: "none" };
}

/** The hold's progress from 0 to 1, for the bar (0 without a hold). */
export function holdProgress(objectives: ObjectivesSnapshot | undefined): number {
  if (objectives === undefined || objectives.channel === "" || objectives.channelTotal === 0) return 0;
  return Math.min(1, objectives.channelHeld / objectives.channelTotal);
}

/** The last finished hold: "Collected the Sun rubbing", or why it came to nothing. */
export function resultLine(model: Pick<HudModel, "objectives">): HudLine {
  const result = model.objectives?.channelResult ?? "";
  if (result === "") return { text: "", state: "none" };
  const [kind, detail] = result.split(":");
  if (kind === "collected") return { text: `Collected the ${typeName(detail!)} rubbing`, state: result };
  if (kind === "claimed") return { text: `Claimed the ${typeName(detail!)} rubbing from the cache`, state: result };
  return { text: "Someone else took that rubbing first", state: result };
}

/**
 * The last duel's settlement (§4, §11), from this player's side: what was stolen and the gold that moved. The loser
 * sees what was taken; both see the gold change; a draw moves nothing.
 */
export function settlementLine(model: Pick<HudModel, "objectives">): HudLine {
  const objectives = model.objectives;
  if (objectives === undefined || objectives.settledRole === "") return { text: "", state: "none" };
  const gold = Math.abs(objectives.goldChange);
  const stolen = objectives.stolen === "" ? "" : typeName(objectives.stolen);
  switch (objectives.settledRole) {
    case "winner":
      if (stolen === "") return { text: gold > 0 ? `Duel won: +${gold} gold (they held nothing you lack)` : "Duel won: nothing to take", state: "winner" };
      return { text: `Duel won: you took the ${stolen} rubbing${gold > 0 ? ` and ${gold} gold` : ""}`, state: `winner:${objectives.stolen}` };
    case "loser":
      if (stolen === "") return { text: gold > 0 ? `Duel lost: -${gold} gold` : "Duel lost: nothing taken", state: "loser" };
      return { text: `Duel lost: they took your ${stolen} rubbing${gold > 0 ? ` and ${gold} gold` : ""}`, state: `loser:${objectives.stolen}` };
    default:
      return { text: "Duel drawn: nothing changed hands", state: "draw" };
  }
}

/**
 * Who picked what the last duel's settlement stole (§4), for both fighters: "You chose Moon" (or "They chose Moon")
 * when the winner picked it, "Taken by default: Moon" when the deadline applied the default. Nothing when nothing moved.
 */
export function choiceLine(model: Pick<HudModel, "objectives">): HudLine {
  const objectives = model.objectives;
  if (objectives === undefined || objectives.stolen === "" || objectives.settledRole === "") return { text: "", state: "none" };
  const stolen = typeName(objectives.stolen);
  if (objectives.settledChoice === "default") return { text: `Taken by default: ${stolen}`, state: "default" };
  if (objectives.settledChoice !== "winner") return { text: "", state: "none" };
  return { text: objectives.settledRole === "winner" ? `You chose ${stolen}` : `They chose ${stolen}`, state: "winner" };
}

/** One option of the winner's theft choice: its key (1, 2, …), its type and its label. */
export interface TheftOption {
  readonly key: string;
  readonly type: string;
  readonly label: string;
}

/**
 * The winner's theft choice (§4), while it is open: the eligible types on keys 1, 2, … and the whole seconds left
 * before the default applies. Undefined for anyone else, or once settled.
 */
export function theftChoice(model: Pick<HudModel, "objectives" | "worldTick">): { options: TheftOption[]; seconds: number; duel: string } | undefined {
  const objectives = model.objectives;
  if (objectives === undefined || objectives.theftDuel === "" || objectives.theftOptions.length === 0) return undefined;
  return {
    duel: objectives.theftDuel,
    seconds: secondsUntil(objectives.theftDeadline, model.worldTick),
    options: objectives.theftOptions.map((type, index) => ({ key: String(index + 1), type, label: `${index + 1}: ${typeName(type)}` })),
  };
}

/** A player's input to an open theft choice: a key (its `KeyboardEvent.code`) or a click on option `n` (1, 2, …). */
export type TheftInput = { readonly code: string } | { readonly option: number };

/**
 * The type a key or a click picks in an open theft choice: Digit/Numpad `n`, or a click on option `n`, is the `n`th
 * option. Undefined when no choice is open or the input names no option.
 */
export function chosenTheftType(choice: Pick<NonNullable<ReturnType<typeof theftChoice>>, "options"> | undefined, input: TheftInput): string | undefined {
  if (choice === undefined) return undefined;
  const key = "code" in input ? /^(?:Digit|Numpad)([1-9])$/.exec(input.code)?.[1] : String(input.option);
  return key === undefined ? undefined : choice.options.find((option) => option.key === key)?.type;
}

function writeLine(element: HTMLElement, line: HudLine): void {
  element.textContent = line.text;
  element.dataset["state"] = line.state;
  if (line.seconds === undefined) delete element.dataset["seconds"];
  else element.dataset["seconds"] = String(line.seconds);
}

function field(root: ParentNode, id: string): HTMLElement {
  const element = root.querySelector<HTMLElement>(`[data-testid="${id}"]`);
  if (element === null) throw new Error(`missing HUD field ${id}`);
  return element;
}

/** "Palm Key, south dock" when moored, "at sea" otherwise. */
export function dockText(dock: number): string {
  return dock === NOT_DOCKED ? "at sea" : dockLabel(defaultSimulationConfig.map, dock);
}

/**
 * What the player can do about docking right now, by the simulation's own rule (`dockInReach`; speed does not matter):
 * nothing to say when moored or far from any dock; otherwise press E.
 */
export function dockHint(ship: Pick<ShipSnapshot, "x" | "y" | "dock">): string {
  if (ship.dock !== NOT_DOCKED) return "";
  const config = defaultSimulationConfig;
  const berth = dockInReach(config, ship.x, ship.y);
  return berth === undefined ? "" : `Press E to dock at ${dockLabel(config.map, berth.id)}`;
}

/** Writes the match status and the latest authoritative (not interpolated) state of the visible ships. */
export function renderHud(root: ParentNode, model: HudModel): void {
  field(root, "hud-code").textContent = model.code;
  field(root, "hud-protocol").textContent = `v${model.protocolVersion}`;
  field(root, "hud-players").textContent = String(model.players);
  field(root, "hud-status").textContent = model.status;
  field(root, "hud-mode").textContent = model.custom ? "custom" : "standard";
  field(root, "hud-self").textContent = model.selfId;
  const own = model.ships.find((ship) => ship.id === model.selfId);
  const dock = field(root, "hud-dock");
  dock.textContent = own === undefined ? "" : dockText(own.dock);
  dock.dataset["dock"] = String(own?.dock ?? NOT_DOCKED);
  field(root, "hud-dock-hint").textContent = own === undefined ? "" : dockHint(own);
  writeLine(field(root, "hud-grapple"), grappleLine(model));
  writeLine(field(root, "hud-incoming"), incomingLine(model));
  writeLine(field(root, "hud-protection"), protectionLine(model));
  writeLine(field(root, "hud-respawn"), respawnLine(model));
  writeLine(field(root, "hud-island"), islandLine(model));
  writeLine(field(root, "hud-cache"), cacheLine(model));
  writeLine(field(root, "hud-hold"), holdLine(model));
  const bar = field(root, "hud-hold-progress");
  const progress = holdProgress(model.objectives);
  bar.hidden = model.objectives?.channel === "" || model.objectives === undefined;
  bar.style.setProperty("--progress", String(progress));
  bar.dataset["held"] = String(model.objectives?.channelHeld ?? 0);
  bar.dataset["total"] = String(model.objectives?.channelTotal ?? 0);
  writeLine(field(root, "hud-result"), resultLine(model));

  const list = field(root, "positions");
  const items = model.ships.map((ship) => {
    const item = document.createElement("li");
    item.dataset["shipId"] = ship.id;
    item.dataset["slot"] = String(ship.slot);
    item.dataset["x"] = String(ship.x);
    item.dataset["y"] = String(ship.y);
    item.dataset["heading"] = String(ship.heading);
    item.dataset["speed"] = String(ship.speed);
    item.dataset["dock"] = String(ship.dock);
    const swatch = document.createElement("span");
    swatch.className = "swatch";
    swatch.style.background = cssColor(slotColor(ship.slot));
    const tile = toTilePosition(defaultSimulationConfig, ship.x, ship.y);
    const who = ship.id === model.selfId ? "you" : ship.id;
    item.append(swatch, `${who}: tile ${tile.tileX},${tile.tileY}, heading ${ship.heading}, speed ${ship.speed}`);
    return item;
  });
  list.replaceChildren(...items);
}

/**
 * The purse, beside the game whether it shows the sea or the arena: gold, rubbings, the last duel's settlement and,
 * for a winner choosing, the theft choice with its countdown (keys 1 and 2, or a click).
 */
export function renderPurse(root: ParentNode, model: Pick<HudModel, "objectives" | "worldTick">): void {
  const objectives = model.objectives;
  const gold = field(root, "purse-gold");
  gold.textContent = objectives === undefined ? "" : String(objectives.gold);
  gold.dataset["gold"] = String(objectives?.gold ?? 0);
  const rubbings = field(root, "purse-rubbings");
  rubbings.textContent = objectives === undefined ? "" : rubbingsText(objectives.rubbings);
  rubbings.dataset["types"] = objectives?.rubbings.join(",") ?? "";
  writeLine(field(root, "purse-settlement"), settlementLine(model));
  const chooser = field(root, "purse-choice");
  writeLine(chooser, choiceLine(model));
  // The server's own ticks, for tests: when the settlement happened and when the choice window would have closed.
  chooser.dataset["settledAt"] = String(objectives?.settledAt ?? 0);
  chooser.dataset["deadline"] = String(objectives?.choiceDeadline ?? 0);
  const panel = field(root, "theft-choice");
  const choice = theftChoice(model);
  panel.hidden = choice === undefined;
  panel.dataset["duel"] = choice?.duel ?? "";
  writeLine(field(root, "theft-deadline"), choice === undefined ? { text: "", state: "none" } : { text: `${choice.seconds} s to choose, then the rarest is taken`, state: "open", seconds: choice.seconds });
  const buttons = field(root, "theft-options");
  const wanted = choice?.options.map((option) => option.type).join(",") ?? "";
  if (buttons.dataset["types"] !== wanted) {
    buttons.dataset["types"] = wanted;
    buttons.replaceChildren(
      ...(choice?.options ?? []).map((option) => {
        const button = document.createElement("button");
        button.type = "button";
        button.dataset["type"] = option.type;
        button.dataset["key"] = option.key;
        button.textContent = option.label;
        return button;
      }),
    );
  }
}

content.content:
import * as Phaser from "phaser";
import { HEADING_COUNT, insideIsland, ISLAND_THEMES, SIGHT_RADIUS_TILES, Terrain, terrainAt } from "@pirate-sea-race/content";
import { encounterRules } from "@pirate-sea-race/content/encounters";
import { defaultSimulationConfig } from "@pirate-sea-race/simulation";
import { ArenaScene, type ArenaSource } from "./arenaScene.js";
import { followScroll, TILE_PIXELS, VIEW_HEIGHT, VIEW_WIDTH } from "./camera.js";
import { FogOfWar } from "./fog.js";
import { drawCaches, drawDuelMarkers, type DrawnCache, type DrawnMarker, type MarkerPen } from "./markers.js";
import { cssColor, slotColor, type MatchView } from "./matchView.js";
import {
  AIM_COLOR,
  CACHE_COLOR,
  CACHE_TRIM,
  DOCK_COLOR,
  DOCK_PLANK,
  FOG_COLOR,
  GRID_COLOR,
  INCOMING_COLOR,
  LAND_COLORS,
  MARKER_COLOR,
  OWN_RING_COLOR,
  PROTECTION_COLOR,
  SEA_COLOR,
  SHOAL_COLOR,
  SHOAL_FLECK,
  SIGHT_COLOR,
  TELEGRAPH_COLOR,
} from "./palette.js";

const { map } = defaultSimulationConfig;
const WORLD_WIDTH = map.widthTiles * TILE_PIXELS;
const WORLD_HEIGHT = map.heightTiles * TILE_PIXELS;
const PIXELS_PER_SUB_UNIT = TILE_PIXELS / map.subUnitsPerTile;
/** The placeholder art was drawn for 16 px tiles; its details scale with the tile. */
const ART_SCALE = TILE_PIXELS / 16;

/** Tile indexes in the generated tileset texture. */
const TILE_SEA = 0;
const TILE_SHOAL = 1;
const TILE_DOCK = 2;
const TILE_LAND = 3;

const MINIMAP_SCALE = 1.25;
const MINIMAP_MARGIN = 8;

/** A grapple's reach and hit area as drawn: the range, and ±hit cone headings either side of the aim. */
const GRAPPLE_RANGE_PIXELS = encounterRules.grapple.rangeTiles * TILE_PIXELS;
const GRAPPLE_HALF_ANGLE = (encounterRules.grapple.hitConeHeadings * 2 * Math.PI) / HEADING_COUNT;

/** A telegraph as drawn this frame, for the DOM report tests read: whose, at whom, and from whose side. */
export interface DrawnTelegraph {
  readonly attackerId: string;
  readonly defenderId: string;
  readonly aim: number;
  /** "own" (this player's aim), "incoming" (aimed at this player) or "other". */
  readonly role: "own" | "incoming" | "other";
}

export type { DrawnCache, DrawnMarker };

/** A ship as drawn this frame, in canvas pixels, for the DOM report tests read. */
export interface DrawnShip {
  readonly id: string;
  readonly x: number;
  readonly y: number;
  readonly color: string;
}

function landTile(tileX: number, tileY: number): number {
  const theme = map.islands.find((island) => insideIsland(island, tileX, tileY))?.theme ?? "tropical";
  return TILE_LAND + ISLAND_THEMES.indexOf(theme);
}

function tileIndex(tileX: number, tileY: number): number {
  switch (terrainAt(map, tileX, tileY)) {
    case Terrain.Land:
      return landTile(tileX, tileY);
    case Terrain.Shoal:
      return TILE_SHOAL;
    case Terrain.Dock:
      return TILE_DOCK;
    default:
      return TILE_SEA;
  }
}

function tileColor(tileX: number, tileY: number): number {
  const index = tileIndex(tileX, tileY);
  if (index >= TILE_LAND) return LAND_COLORS[ISLAND_THEMES[index - TILE_LAND]!];
  return [SEA_COLOR, SHOAL_COLOR, DOCK_COLOR][index]!;
}

/**
 * Draws the sea: the tile map from content, the ships the server sent at interpolated positions, a camera that
 * follows the player's ship, the sight circle, and a minimap whose fog clears along the player's path. The encounters
 * of §6 are drawn over it: each grapple's telegraph (its reach and hit area along the locked aim, filling in as the
 * windup runs out; the player's own in green, one aimed at the player in red with a warning arrow on its ship, others
 * in sand), a duel marker (crossed swords and the elapsed time) where a duel runs, and a ring round the player's ship
 * while it is protected; and a chest on each recovery cache's dock in sight (§12, no contents). Each frame it records
 * what it drew in data attributes on the report element (`data-drawn-ships`, `data-telegraphs`, `data-markers`,
 * `data-caches`, `data-camera`, `data-fog-revealed`, and once `data-minimap`: the minimap's left, top and scale on
 * the canvas) for the browser tests.
 */
export class SeaScene extends Phaser.Scene {
  private readonly shipGraphics = new Map<string, Phaser.GameObjects.Graphics>();
  private encounterGraphics!: Phaser.GameObjects.Graphics;
  private readonly markerLabels: Phaser.GameObjects.Text[] = [];
  private lastEncounterReport = "";
  private readonly fog = new FogOfWar(map.widthTiles, map.heightTiles, SIGHT_RADIUS_TILES);
  private minimap!: Phaser.Textures.CanvasTexture;
  private minimapMarks!: Phaser.GameObjects.Graphics;
  private sight!: Phaser.GameObjects.Graphics;
  private lastReport = "";

  constructor(
    private readonly view: MatchView,
    private readonly report: HTMLElement,
  ) {
    super("sea");
  }

  create(): void {
    this.createTerrain();
    this.sight = this.add.graphics();
    this.sight.lineStyle(1, SIGHT_COLOR, 0.45);
    this.sight.strokeCircle(0, 0, SIGHT_RADIUS_TILES * TILE_PIXELS);
    this.sight.setDepth(1);
    this.encounterGraphics = this.add.graphics().setDepth(1.5);
    this.createMinimap();
  }

  /** The tile map, as a Phaser tilemap over a tileset texture drawn here in placeholder colours. */
  private createTerrain(): void {
    const kinds = TILE_LAND + ISLAND_THEMES.length;
    const tileset = this.textures.createCanvas("terrain-tiles", kinds * TILE_PIXELS, TILE_PIXELS)!;
    const context = tileset.getContext();
    const paint = (index: number, color: number) => {
      context.fillStyle = cssColor(color);
      context.fillRect(index * TILE_PIXELS, 0, TILE_PIXELS, TILE_PIXELS);
    };
    paint(TILE_SEA, SEA_COLOR);
    paint(TILE_SHOAL, SHOAL_COLOR);
    context.fillStyle = cssColor(SHOAL_FLECK);
    for (const [x, y] of [[3, 4], [10, 2], [6, 10], [13, 12], [2, 13]] as const) {
      context.fillRect(TILE_SHOAL * TILE_PIXELS + Math.round(x * ART_SCALE), Math.round(y * ART_SCALE), 2 * ART_SCALE, 2 * ART_SCALE);
    }
    paint(TILE_DOCK, DOCK_COLOR);
    context.fillStyle = cssColor(DOCK_PLANK);
    for (const y of [4, 9, 14]) context.fillRect(TILE_DOCK * TILE_PIXELS, Math.round(y * ART_SCALE), TILE_PIXELS, 1);
    ISLAND_THEMES.forEach((theme, index) => paint(TILE_LAND + index, LAND_COLORS[theme]));
    tileset.refresh();

    // Open sea is left empty (-1): the camera's background is the sea, so the layer draws only the few land, shoal
    // and dock tiles in view. Drawing every sea tile too costs a software renderer most of its frame rate.
    const data = Array.from({ length: map.heightTiles }, (_, tileY) =>
      Array.from({ length: map.widthTiles }, (_, tileX) => {
        const index = tileIndex(tileX, tileY);
        return index === TILE_SEA ? -1 : index;
      }),
    );
    const tilemap = this.make.tilemap({ data, tileWidth: TILE_PIXELS, tileHeight: TILE_PIXELS });
    const tiles = tilemap.addTilesetImage("terrain", "terrain-tiles", TILE_PIXELS, TILE_PIXELS, 0, 0)!;
    tilemap.createLayer(0, tiles, 0, 0);

    // A chart grid every eight tiles, so open water shows the ship's motion.
    const grid = this.add.graphics();
    grid.lineStyle(1, GRID_COLOR, 0.6);
    for (let tile = 0; tile <= map.widthTiles; tile += 8) grid.lineBetween(tile * TILE_PIXELS, 0, tile * TILE_PIXELS, WORLD_HEIGHT);
    for (let tile = 0; tile <= map.heightTiles; tile += 8) grid.lineBetween(0, tile * TILE_PIXELS, WORLD_WIDTH, tile * TILE_PIXELS);

    for (const island of map.islands) {
      const label = this.add.text((island.tileX + island.widthTiles / 2) * TILE_PIXELS, (island.tileY - 1.2) * TILE_PIXELS, island.name, {
        fontFamily: "system-ui, sans-serif",
        fontSize: `${12 * ART_SCALE}px`,
        color: "#e8f1f5",
      });
      label.setOrigin(0.5, 0.5).setAlpha(0.85);
    }
  }

  /** The minimap: one pixel per tile, fogged until the player's ship has seen it. */
  private createMinimap(): void {
    this.minimap = this.textures.createCanvas("minimap", map.widthTiles, map.heightTiles)!;
    const context = this.minimap.getContext();
    context.fillStyle = cssColor(FOG_COLOR);
    context.fillRect(0, 0, map.widthTiles, map.heightTiles);
    this.minimap.refresh();
    const left = VIEW_WIDTH - MINIMAP_MARGIN - map.widthTiles * MINIMAP_SCALE;
    const frame = this.add.graphics().setScrollFactor(0).setDepth(10);
    frame.lineStyle(2, 0x9bb8c6, 0.9);
    frame.strokeRect(left - 1, MINIMAP_MARGIN - 1, map.widthTiles * MINIMAP_SCALE + 2, map.heightTiles * MINIMAP_SCALE + 2);
    this.add.image(left, MINIMAP_MARGIN, "minimap").setOrigin(0, 0).setScale(MINIMAP_SCALE).setScrollFactor(0).setDepth(10);
    this.minimapMarks = this.add.graphics().setScrollFactor(0).setDepth(11);
    this.report.dataset["minimap"] = `${left},${MINIMAP_MARGIN},${MINIMAP_SCALE}`;
  }

  private revealFog(x: number, y: number): void {
    const fresh = this.fog.revealAround(Math.floor(x / TILE_PIXELS), Math.floor(y / TILE_PIXELS));
    if (fresh.length === 0) return;
    const context = this.minimap.getContext();
    for (const [tileX, tileY] of fresh) {
      context.fillStyle = cssColor(tileColor(tileX, tileY));
      context.fillRect(tileX, tileY, 1, 1);
    }
    this.minimap.refresh();
    this.report.dataset["fogRevealed"] = String(this.fog.revealedCount);
  }

  override update(): void {
    const now = performance.now();
    const own = this.view.renderPosition(this.view.selfId, now);
    if (own !== undefined) {
      const x = own.x * PIXELS_PER_SUB_UNIT;
      const y = own.y * PIXELS_PER_SUB_UNIT;
      const scroll = followScroll(x, y);
      this.cameras.main.setScroll(scroll.x, scroll.y);
      this.sight.setPosition(x, y);
      this.revealFog(x, y);
    }
    const camera = this.cameras.main;
    const minimapLeft = VIEW_WIDTH - MINIMAP_MARGIN - map.widthTiles * MINIMAP_SCALE;
    this.minimapMarks.clear();

    const drawn: DrawnShip[] = [];
    const present = new Set<string>();
    for (const ship of this.view.ships()) {
      const position = this.view.renderPosition(ship.id, now);
      if (position === undefined) continue;
      present.add(ship.id);
      const mine = ship.id === this.view.selfId;
      let graphics = this.shipGraphics.get(ship.id);
      if (graphics === undefined) {
        graphics = this.drawShip(slotColor(ship.slot), mine);
        this.shipGraphics.set(ship.id, graphics);
      }
      const x = position.x * PIXELS_PER_SUB_UNIT;
      const y = position.y * PIXELS_PER_SUB_UNIT;
      graphics.setPosition(x, y);
      graphics.setRotation((ship.heading * 2 * Math.PI) / HEADING_COUNT);
      drawn.push({ id: ship.id, x: Math.round(x - camera.scrollX), y: Math.round(y - camera.scrollY), color: cssColor(slotColor(ship.slot)) });
      this.minimapMarks.fillStyle(mine ? OWN_RING_COLOR : slotColor(ship.slot), 1);
      this.minimapMarks.fillRect(minimapLeft + (x / TILE_PIXELS) * MINIMAP_SCALE - 1.5, MINIMAP_MARGIN + (y / TILE_PIXELS) * MINIMAP_SCALE - 1.5, 3, 3);
    }
    for (const [id, graphics] of this.shipGraphics) {
      if (present.has(id)) continue;
      graphics.destroy();
      this.shipGraphics.delete(id);
    }
    const report = JSON.stringify(drawn);
    if (report !== this.lastReport) {
      this.report.dataset["drawnShips"] = report;
      this.lastReport = report;
    }
    this.drawEncounters(now);
    this.report.dataset["camera"] = `${camera.scrollX},${camera.scrollY}`;
  }

  /** Telegraphs, duel markers and the player's protection ring (§6), under the ships. */
  private drawEncounters(now: number): void {
    const graphics = this.encounterGraphics;
    graphics.clear();
    const camera = this.cameras.main;
    const tick = this.view.worldTick();
    const pixels = (position: { x: number; y: number }) => ({ x: position.x * PIXELS_PER_SUB_UNIT, y: position.y * PIXELS_PER_SUB_UNIT });

    const telegraphs: DrawnTelegraph[] = [];
    for (const grapple of this.view.grapples()) {
      const role = grapple.attackerId === this.view.selfId ? "own" : grapple.defenderId === this.view.selfId ? "incoming" : "other";
      telegraphs.push({ attackerId: grapple.attackerId, defenderId: grapple.defenderId, aim: grapple.aim, role });
      const from = this.view.renderPosition(grapple.attackerId, now);
      if (from === undefined) continue;
      const { x, y } = pixels(from);
      const color = role === "own" ? AIM_COLOR : role === "incoming" ? INCOMING_COLOR : TELEGRAPH_COLOR;
      const angle = (grapple.aim * 2 * Math.PI) / HEADING_COUNT;
      const progress = Math.min(1, Math.max(0, (tick - grapple.startTick) / Math.max(1, grapple.landTick - grapple.startTick)));
      // The hit area: a wedge whose fill deepens as the windup runs out, and the aim line down its middle.
      graphics.fillStyle(color, 0.12 + 0.3 * progress);
      graphics.slice(x, y, GRAPPLE_RANGE_PIXELS, angle - GRAPPLE_HALF_ANGLE, angle + GRAPPLE_HALF_ANGLE, false);
      graphics.fillPath();
      graphics.lineStyle(2, color, 0.9);
      graphics.lineBetween(x, y, x + Math.cos(angle) * GRAPPLE_RANGE_PIXELS, y + Math.sin(angle) * GRAPPLE_RANGE_PIXELS);
      if (role !== "incoming") continue;
      // The target's warning: an arrow on its own ship pointing back at the attacker.
      const own = this.view.renderPosition(this.view.selfId, now);
      if (own === undefined) continue;
      const at = pixels(own);
      const back = Math.atan2(y - at.y, x - at.x);
      const tip = { x: at.x + Math.cos(back) * 30 * ART_SCALE / 2, y: at.y + Math.sin(back) * 30 * ART_SCALE / 2 };
      graphics.fillStyle(INCOMING_COLOR, 1);
      graphics.fillTriangle(
        tip.x,
        tip.y,
        at.x + Math.cos(back + 0.35) * 16 * ART_SCALE / 2,
        at.y + Math.sin(back + 0.35) * 16 * ART_SCALE / 2,
        at.x + Math.cos(back - 0.35) * 16 * ART_SCALE / 2,
        at.y + Math.sin(back - 0.35) * 16 * ART_SCALE / 2,
      );
    }

    const labels = this.markerLabels;
    const pen: MarkerPen = {
      swords: (x, y, size) => {
        graphics.lineStyle(3, MARKER_COLOR, 1);
        graphics.lineBetween(x - size, y - size, x + size, y + size);
        graphics.lineBetween(x - size, y + size, x + size, y - size);
        // Hilts across each blade's lower end.
        graphics.lineBetween(x - size - 3, y + size - 5, x - size + 5, y + size + 3);
        graphics.lineBetween(x + size + 3, y + size - 5, x + size - 5, y + size + 3);
      },
      label: (index, x, y, text) => {
        let label = labels[index];
        if (label === undefined) {
          label = this.add.text(0, 0, "", { fontFamily: "system-ui, sans-serif", fontSize: `${9 * ART_SCALE}px`, color: cssColor(MARKER_COLOR) });
          label.setOrigin(0.5, 0).setDepth(3);
          labels.push(label);
        }
        label.setPosition(x, y).setText(text).setVisible(true);
      },
      chest: (x, y, half) => {
        graphics.fillStyle(CACHE_COLOR, 1);
        graphics.fillRect(x - half, y - half * 0.7, half * 2, half * 1.4);
        graphics.lineStyle(2, CACHE_TRIM, 1);
        graphics.strokeRect(x - half, y - half * 0.7, half * 2, half * 1.4);
        graphics.lineBetween(x - half, y - half * 0.1, x + half, y - half * 0.1);
      },
    };
    const markers = drawDuelMarkers(pen, this.view.markers(), tick, { x: camera.scrollX, y: camera.scrollY });
    for (const label of labels.slice(markers.length)) label.setVisible(false);
    const caches = drawCaches(pen, this.view.caches(), { x: camera.scrollX, y: camera.scrollY });

    const status = this.view.status();
    const own = this.view.renderPosition(this.view.selfId, now);
    if (status !== undefined && status.protection !== "" && own !== undefined) {
      const { x, y } = pixels(own);
      graphics.lineStyle(2, PROTECTION_COLOR, 0.35 + 0.35 * Math.abs(Math.sin(now / 250)));
      graphics.strokeCircle(x, y, 13 * ART_SCALE);
    }

    const report = JSON.stringify({ telegraphs, markers, caches });
    if (report !== this.lastEncounterReport) {
      this.report.dataset["telegraphs"] = JSON.stringify(telegraphs);
      this.report.dataset["markers"] = JSON.stringify(markers);
      this.report.dataset["caches"] = JSON.stringify(caches);
      this.lastEncounterReport = report;
    }
  }

  /** A round hull with a bow pointing along +x; the player's own ship gets a pale ring. */
  private drawShip(color: number, own: boolean): Phaser.GameObjects.Graphics {
    const graphics = this.add.graphics();
    graphics.setDepth(2);
    graphics.fillStyle(color, 1);
    graphics.fillCircle(0, 0, 6 * ART_SCALE);
    graphics.fillTriangle(3 * ART_SCALE, -5 * ART_SCALE, 12 * ART_SCALE, 0, 3 * ART_SCALE, 5 * ART_SCALE);
    if (own) {
      graphics.lineStyle(2, OWN_RING_COLOR, 1);
      graphics.strokeCircle(0, 0, 10 * ART_SCALE);
    }
    return graphics;
  }
}

/**
 * The match's one game (one Phaser game per page): the sea, and the arena it gives way to for a duel at sea. The page
 * switches between them; `data-scene` on the parent says which is showing.
 *
 * It uses Phaser's canvas renderer, like the standalone arena: on a machine without a GPU, WebGL runs in software on
 * the main thread and starves the duel client's 4 ms tick (measured in headless Chromium by the `sea-duel` browser
 * test: a 95th-percentile tick interval of 135 ms with `Phaser.AUTO`); the canvas renderer keeps it under a frame.
 */
export class MatchGame {
  readonly game: Phaser.Game;

  constructor(
    private readonly parent: HTMLElement,
    view: MatchView,
  ) {
    this.game = new Phaser.Game({
      type: Phaser.CANVAS,
      parent,
      width: VIEW_WIDTH,
      height: VIEW_HEIGHT,
      backgroundColor: SEA_COLOR,
      banner: false,
      audio: { noAudio: true },
      // The sea starts; the arena is added asleep and started with each duel's source.
      scene: [new SeaScene(view, parent), new ArenaScene(parent)],
    });
    parent.dataset["scene"] = "sea";
  }

  /** A duel at sea: the sea sleeps (it keeps its state) and the arena draws this duel. */
  showArena(source: ArenaSource): void {
    this.game.scene.sleep("sea");
    this.game.scene.start("arena", { source });
    this.parent.dataset["scene"] = "arena";
  }

  /** Back to the world: the arena stops and the sea wakes where it was. */
  showSea(): void {
    this.game.scene.stop("arena");
    this.game.scene.wake("sea");
    this.parent.dataset["scene"] = "sea";
  }
}
import { INTERPOLATION_DELAY_MS, SnapshotBuffer } from "./interpolation.js";

/** A ship as the server last sent it: only the client's own ship and ships in its sight ever arrive (§16). */
export interface ShipSnapshot {
  readonly id: string;
  readonly slot: number;
  readonly x: number;
  readonly y: number;
  readonly heading: number;
  readonly speed: number;
  /** The dock it is moored at, or -1 at sea. */
  readonly dock: number;
}

/** A telegraphed grapple (§6) as the server last sent it: only those whose attacker is in sight, or aimed at us. */
export interface GrappleSnapshot {
  readonly attackerId: string;
  readonly defenderId: string;
  /** The aim, a heading of 64 locked when the grapple started. */
  readonly aim: number;
  readonly startTick: number;
  readonly landTick: number;
}

/** A duel marker (§6) as the server last sent it: only those in sight. */
export interface MarkerSnapshot {
  readonly x: number;
  readonly y: number;
  /** The world tick the duel began; its elapsed time counts from here. */
  readonly startTick: number;
}

/** This player's own encounter status (§6): its mode, protection, grapple cooldown and respawn, in world ticks. */
export interface StatusSnapshot {
  readonly mode: string;
  readonly protection: string;
  readonly protectedUntil: number;
  readonly cooldownUntil: number;
  readonly respawnAt: number;
}

/**
 * This player's own rubbings and gold (§4, §11, §12), as the server last sent them in its private status: only the
 * player's own entry ever arrives (§16). Lists are rubbing type names in type order; the island's and the cache's
 * types are empty unless the ship is moored there.
 */
export interface ObjectivesSnapshot {
  readonly gold: number;
  readonly rubbings: readonly string[];
  readonly islandTypes: readonly string[];
  readonly cacheTypes: readonly string[];
  /** What holding E works on here: "collect:<type>", "claim:<type>", or "". */
  readonly target: string;
  /** The hold in progress ("collect" or "claim", or ""), its type, and its ticks held and needed. */
  readonly channel: string;
  readonly channelType: string;
  readonly channelHeld: number;
  readonly channelTotal: number;
  /** The last finished hold ("collected:<type>", "claimed:<type>", "failed:<reason>" or "") and its world tick. */
  readonly channelResult: string;
  readonly channelResultAt: number;
  /** While this player chooses what to steal: the duel's lobby key, the eligible types and the deadline tick. */
  readonly theftDuel: string;
  readonly theftOptions: readonly string[];
  readonly theftDeadline: number;
  /** The last duel settlement: "winner", "loser", "draw" or "", the type stolen, the gold change and its tick. */
  readonly settledRole: string;
  readonly stolen: string;
  readonly goldChange: number;
  readonly settledAt: number;
  /** Who picked the stolen type ("winner", "default", "none" or "") and that duel's choice deadline tick. */
  readonly settledChoice: string;
  readonly choiceDeadline: number;
}

/** The private status fields as the server sends them (lists comma-separated). */
export interface ObjectivesStatusFields {
  readonly gold: number;
  readonly rubbings: string;
  readonly islandTypes: string;

